xdt=id=>{const e=S.exp.find(x=>x.id==id);if(!e)return;const it=e.items&&e.items.length?e.items:null;MD(`<div class="bar" style="margin:0"><h3>🧾 Detail Pengeluaran</h3><button onclick="MC()" title="Tutup">✕</button></div><p class="hn">${e.d} · ${E(e.cat)}${e.sup?' · '+E(e.sup):''}</p>${it?`<div class="sc" style="max-height:300px"><table>${th(['Item','Qty','Harga satuan','Subtotal'])}${it.map(i=>`<tr><td>${E(i.n)}</td><td>${i.q}</td><td>${R(i.p)}</td><td>${R(i.q*i.p)}</td></tr>`).join('')}</table></div>`:`<p>${E(e.desc)}</p>`}${e.note?`<p class="hn">Catatan: ${E(e.note)}</p>`:''}<h3 style="text-align:right">Total ${R(e.amt)}</h3><div class="bar"><button onclick="MC();if(confirm('Hapus catatan ini?')){S.exp=S.exp.filter(x=>x.id!='${e.id}');save();go()}">🗑️ Hapus</button><span><button onclick="xpr('${e.id}')">✏️ Edit</button> <button class="btn" onclick="MC()">Tutup</button></span></div>`)},
