emv=()=>{const d=EM.dim,a=d?ar(d):1,cm=d&&d.u=='cm',c=N(EM.cost),h=d?c/a/(cm?1e4:1):0,g=(j,x)=>j>0?((j-x)/j*100).toFixed(1)+'%':'—',e=$('#emv');if(e)e.innerHTML=`HPP: ${R(c)} / ${E(d?d.n:EM.unit)}${d?` (${hf(h)} / ${cm?'cm²':'m²'})`:''}<br>Margin harga jual: ${g(N(EM.sell),c)}${d?`<br>Margin harga jual / ${cm?'cm²':'m²'}: ${g(N(EM.sellU),h)}`:''}`},
