pv=()=>{const e=$('#pv');if(!e)return;const d={p:$('#npj').value,l:$('#nlb').value,u:$('#nu2').value},a=ar(d);e.textContent=fz()&&a?`Luas 1 ${$('#nk').value} = ${+a.toFixed(4)} m² · Harga ≈ ${$('#nu2').value=='cm'?'Rp '+(N($('#nhg').value)/a/1e4).toLocaleString('id-ID',{maximumFractionDigits:2})+' per cm²':R(N($('#nhg').value)/a)+' per m²'} · Stok total ${+(a*N($('#njr').value)).toFixed(2)} m²${N($('#njl').value)>0&&N($('#nhg').value)>0?` · Margin jual roll/lembar ${((N($('#njl').value)-N($('#nhg').value))/N($('#njl').value)*100).toFixed(1)}%`:''}`:''},
