am=()=>{const n=$('#nn').value.trim();if(!n)return alert('Isi nama bahan');
if(fz()){const d={p:N($('#npj').value),l:N($('#nlb').value),u:$('#nu2').value,n:$('#nk').value},a=ar(d);if(!a)return alert('Isi panjang dan lebar');S.mats.push({id:uid(),name:n,unit:'m²',dim:d,stock:+(a*N($('#njr').value)).toFixed(3),min:+(a*N($('#nmr').value)).toFixed(3),cost:N($('#nhg').value)/a,sell:N($('#njl').value)||'',sellU:N($('#njm').value)?N($('#njm').value)*(d.u=='cm'?1e4:1):''})}
else S.mats.push({id:uid(),name:n,unit:$('#nsu').value||'pcs',stock:N($('#nst').value),min:N($('#nms').value),cost:N($('#nhs').value),sell:N($('#njs').value)||''});save();go()};
