MV=m=>m.dim?+(m.min/ar(m.dim)).toFixed(2):m.min,CV=m=>m.dim?Math.round(m.cost*ar(m.dim)):m.cost,
MM=(id,k,v)=>{const m=mat(id),a=m.dim?ar(m.dim):1;if(k=='name'){if(!v.trim())return go();m.name=v.trim()}else if(k=='sell')m.sell=String(v).trim()===''?'':N(v);else if(k=='sellU')m.sellU=String(v).trim()===''?'':N(v)*(m.dim&&m.dim.u=='cm'?1e4:1);else if(k=='min')m.min=+(N(v)*a).toFixed(3);else m.cost=m.dim?N(v)/a:N(v);save();go()},
